import{_ as r,o as e,c as t,a2 as l}from"./chunks/framework.CRFziyHp.js";const f=JSON.parse('{"title":"骑手","description":"","frontmatter":{},"headers":[],"relativePath":"features/rider.md","filePath":"features/rider.md","lastUpdated":1785013113000}'),o={name:"features/rider.md"};function i(n,a,s,h,u,d){return e(),t("div",null,[...a[0]||(a[0]=[l('<h1 id="骑手" tabindex="-1">骑手 <a class="header-anchor" href="#骑手" aria-label="Permalink to &quot;骑手&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>审核用户骑手入驻申请，管理骑手账号与在线状态，支撑外卖派单与跑腿接单。</p><h2 id="前置条件" tabindex="-1">前置条件 <a class="header-anchor" href="#前置条件" aria-label="Permalink to &quot;前置条件&quot;">​</a></h2><ul><li>骑手模块已在授权中开通（<strong>商户管理 → 骑手</strong> 可见）。</li><li><a href="/features/takeaway">外卖</a> 或 <a href="/features/errand">跑腿</a> 至少一项已在对应区域配置中启用。</li><li><a href="/features/map">高德地图</a> 已配置（骑手定位与导航）。</li></ul><h2 id="管理后台配置步骤" tabindex="-1">管理后台配置步骤 <a class="header-anchor" href="#管理后台配置步骤" aria-label="Permalink to &quot;管理后台配置步骤&quot;">​</a></h2><h3 id="_1-骑手审核" tabindex="-1">1. 骑手审核 <a class="header-anchor" href="#_1-骑手审核" aria-label="Permalink to &quot;1. 骑手审核&quot;">​</a></h3><p>路径：<strong>商户管理 → 骑手 → 骑手审核</strong></p><ul><li>查看待审核申请（实名、交通工具、所属区域等）</li><li><strong>通过</strong> 后用户获得骑手身份，可登录骑手端接单</li><li><strong>拒绝</strong> 并填写原因（若页面支持）</li></ul><p>新站上线前建议先通过 1～2 名测试骑手，用于验证派单链路。</p><h3 id="_2-骑手管理" tabindex="-1">2. 骑手管理 <a class="header-anchor" href="#_2-骑手管理" aria-label="Permalink to &quot;2. 骑手管理&quot;">​</a></h3><p>路径：<strong>商户管理 → 骑手 → 骑手管理</strong></p><ul><li>查看已入驻骑手列表</li><li>禁用 / 启用账号、调整所属区域（以页面为准）</li><li>查看在线状态、历史单量</li></ul><h3 id="_3-与派单的关系" tabindex="-1">3. 与派单的关系 <a class="header-anchor" href="#_3-与派单的关系" aria-label="Permalink to &quot;3. 与派单的关系&quot;">​</a></h3><p>骑手本身在 <strong>骑手审核 / 骑手管理</strong> 维护；<strong>派单策略</strong> 在 <strong>商户管理 → 外卖 → 区域外卖配置</strong> 中设置。两者都就绪后，外卖 / 跑腿订单才能被正常接单。</p><h2 id="区域配置" tabindex="-1">区域配置 <a class="header-anchor" href="#区域配置" aria-label="Permalink to &quot;区域配置&quot;">​</a></h2><p>骑手通常绑定 <strong>服务区域</strong>（申请时选择或审核时指定）：</p><ul><li>仅服务本区域订单的用户应审核到对应 region</li><li>跨区派单是否允许由 <strong>区域外卖配置</strong> 决定，非骑手列表单独字段</li></ul><h2 id="验证是否生效" tabindex="-1">验证是否生效 <a class="header-anchor" href="#验证是否生效" aria-label="Permalink to &quot;验证是否生效&quot;">​</a></h2><ol><li>测试用户提交骑手申请，在 <strong>骑手审核</strong> 中通过。</li><li>骑手端（或骑手模式）上线，状态为可接单。</li><li>在已开通外卖 / 跑腿的区域下一单，该骑手能收到派单并成功完成，<strong>外卖订单 / 跑腿订单</strong> 状态变为已完成。</li></ol><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>侧栏没有骑手菜单</strong></p><ul><li>骑手模块未授权；或 <strong>商户管理</strong> 整体未解锁。</li></ul><p><strong>审核通过但仍无法接单</strong></p><ul><li>骑手是否处于 <strong>启用</strong> 状态；是否已上线 / 开启听单。</li><li>订单所在区域与骑手服务区域是否一致。</li></ul><p><strong>派单不到骑手</strong></p><ul><li>该区域 <strong>区域外卖配置</strong> 派单策略、骑手在线人数。</li><li>地图定位异常导致距离过滤，见 <a href="/features/map">地图</a>。</li></ul><p><strong>如何取消骑手资格</strong></p><ul><li>在 <strong>骑手管理</strong> 中禁用账号；必要时在 <strong>用户管理</strong> 中进一步处理。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/features/takeaway">外卖</a></li><li><a href="/features/errand">跑腿</a></li><li><a href="/features/map">地图与定位</a></li></ul>',31)])])}const c=r(o,[["render",i]]);export{f as __pageData,c as default};
